"""Larger randomized tests using a DPLL solver for 3-SAT and a smarter
1-in-3-SAT solver, to check reduce.py on instances too big for naive brute
force of the reduced formula.
"""

from __future__ import annotations

import itertools
import random

from problems import OneInThreeSat, ThreeSat
from reduce import reduce


# ---- DPLL for 3-SAT (clauses are lists of int literals) ----

def dpll(clauses, assignment):
    # Simplify clauses under current assignment.
    simplified = []
    for clause in clauses:
        sat = False
        rest = []
        for lit in clause:
            v = abs(lit)
            val = assignment.get(v)
            if val is None:
                rest.append(lit)
            elif (lit > 0) == val:
                sat = True
                break
        if sat:
            continue
        if not rest:
            return False  # empty clause -> conflict
        simplified.append(rest)

    if not simplified:
        return True

    # Unit propagation.
    for clause in simplified:
        if len(clause) == 1:
            lit = clause[0]
            v = abs(lit)
            val = lit > 0
            if v in assignment and assignment[v] != val:
                return False
            new = dict(assignment)
            new[v] = val
            return dpll(simplified, new)

    # Choose a variable.
    lit = simplified[0][0]
    v = abs(lit)
    for val in (True, False):
        new = dict(assignment)
        new[v] = val
        if dpll(simplified, new):
            return True
    return False


def solve_three_sat_dpll(instance):
    return dpll(instance["clauses"], {})


# ---- 1-in-3-SAT via brute force (small m) ----

def solve_one_in_three_sat(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product((False, True), repeat=m):
        ok = True
        for clause in clauses:
            if sum(1 for v in clause if bits[v - 1]) != 1:
                ok = False
                break
        if ok:
            return True
    return not clauses


def all_positive_clauses(m):
    return [list(c) for c in itertools.combinations(range(1, m + 1), 3)]


def main():
    rng = random.Random(999)
    tests_run = 0
    tests_passed = 0

    # Random larger instances: m up to 9, several clauses -> reduced has
    # up to 9 + 3*k vars; DPLL handles it.
    for _ in range(3000):
        m = rng.randint(3, 9)
        pool = all_positive_clauses(m)
        k = rng.randint(0, 8)
        clauses = [list(rng.choice(pool)) for _ in range(k)]
        inst = {"num_vars": m, "clauses": clauses}
        OneInThreeSat.validate(inst)

        expected = solve_one_in_three_sat(inst)
        reduced = reduce(inst)

        tests_run += 1
        try:
            ThreeSat.validate(reduced)
            tests_passed += 1
        except Exception as e:
            print("INVALID TARGET", inst, e)
            continue

        tests_run += 1
        got = solve_three_sat_dpll(reduced)
        if got == expected:
            tests_passed += 1
        else:
            print("MISMATCH", inst, "expected", expected, "got", got)

    print(f"tests_run={tests_run} tests_passed={tests_passed}")
    return tests_run, tests_passed


if __name__ == "__main__":
    main()
